@import url("https://fonts.googleapis.com/css2?family=Crimson+Pro:ital,wght@0,500;0,700;1,500&family=Readex+Pro:wght@400;500;600&display=swap");
:root{--gn:#0F3D2E;--gn2:#1A5541;--cp:#B8733A;--cp2:#9A5C28;--st:#E9EEEA;--ink:#17231E;--gr:#56625C;--ln:#D8E0DA;--h:"Crimson Pro",Georgia,serif;--b:"Readex Pro",system-ui,sans-serif}
*,*::before,*::after{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;font-family:var(--b);font-size:17px;line-height:1.65;color:var(--ink);background:#fff}
img{max-width:100%;height:auto;display:block}a{color:inherit}h1,h2,h3{font-family:var(--h);font-weight:500;margin:0;line-height:1.08}
.wrap{max-width:1200px;margin:0 auto;padding:0 22px}.skip{position:absolute;left:-999px}.skip:focus{left:10px;top:10px;background:var(--cp);color:#fff;padding:8px;z-index:99}
:focus-visible{outline:3px solid var(--cp);outline-offset:2px}
.hero{position:relative;color:#fff;min-height:660px;display:flex;flex-direction:column;background:var(--gn)}
.hero>img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}.hero:after{content:"";position:absolute;inset:0;background:linear-gradient(0deg,rgba(15,61,46,.92) 10%,rgba(15,61,46,.35) 60%,rgba(15,61,46,.6))}
.nav{position:relative;z-index:5;display:flex;justify-content:space-between;align-items:center;height:84px}
.logo{display:flex;gap:10px;align-items:center;text-decoration:none;font-family:var(--h);font-size:26px;font-weight:700}
.menu{display:flex;gap:26px;list-style:none;margin:0;padding:0;font-weight:500}.menu a{text-decoration:none}.menu a:hover{color:#F1C7A2}
.burger{display:none;background:none;border:2px solid #fff;color:#fff;width:44px;height:40px;font-size:20px;cursor:pointer}
.hc{position:relative;z-index:3;margin-top:auto;padding-bottom:60px}.hero h1{font-size:clamp(50px,7.4vw,108px);max-width:12em}.hero h1 em{color:#F1C7A2}
.hero p{font-size:19px;max-width:34em;color:#E1EAE5;margin:18px 0 26px}
.hs{display:flex;max-width:620px;background:#fff;border-radius:4px;overflow:hidden}.hs input{flex:1;min-width:0;border:0;font:17px var(--b);padding:16px 18px;color:var(--ink)}.hs button{border:0;background:var(--cp);color:#fff;font:600 16px var(--b);padding:0 22px;cursor:pointer}
.nums{background:var(--gn2);color:#fff}.nums .wrap{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:20px;padding-top:26px;padding-bottom:26px}.nums b{display:block;font-family:var(--h);font-size:44px;line-height:1;font-weight:500}.nums span{color:#C6D6CD;font-size:15px}
section{padding:86px 0}.sh{max-width:680px;margin-bottom:30px}.sh h2{font-size:clamp(38px,4.8vw,60px);color:var(--gn)}.sh p{color:var(--gr);margin:10px 0 0;font-size:18px}
.fd{display:grid;grid-template-columns:270px 1fr;gap:36px;align-items:start}.fd>div{min-width:0}
.fl{background:var(--st);border-radius:6px;padding:22px;position:sticky;top:16px}.fl h3{font-size:24px;margin-bottom:12px}
.fl label,.fl legend{display:block;font-weight:600;font-size:15px;margin-bottom:6px}.fl input[type=search],.fl select{width:100%;font:16px var(--b);padding:11px;border:1px solid #BFCBC3;border-radius:4px;margin-bottom:16px;background:#fff;color:var(--ink)}
.fl fieldset{border:0;padding:0;margin:0 0 16px}.fl .ck{display:flex;gap:8px;align-items:center;font-weight:400;margin:6px 0}.fl .ck input{width:18px;height:18px;accent-color:var(--gn)}
.fl .rs{background:none;border:0;color:var(--cp2);font:600 15px var(--b);text-decoration:underline;cursor:pointer;padding:0}
.rh{display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;margin-bottom:14px;color:var(--gr)}.rh b{color:var(--ink)}
.sl{background:var(--gn);color:#fff;border-radius:30px;padding:6px 14px;font-size:15px}
.cr{border-top:1px solid var(--ln);padding:20px 0;display:grid;grid-template-columns:1fr auto;gap:6px 20px}
.cr h3{font-size:27px;color:var(--gn)}.cr .lv{font-size:14px;font-weight:600;color:var(--cp2)}
.cr dl{display:flex;flex-wrap:wrap;gap:6px 22px;margin:6px 0 0;font-size:15px;color:var(--gr)}.cr dt{display:inline;font-weight:600;color:var(--ink)}.cr dd{display:inline;margin:0 0 0 4px}
.cr button{grid-row:1/3;grid-column:2;align-self:center;font:600 15px var(--b);background:#fff;border:1px solid var(--gn);color:var(--gn);border-radius:4px;padding:10px 14px;cursor:pointer;white-space:nowrap}.cr button[aria-pressed=true]{background:var(--gn);color:#fff}
.none{padding:30px;background:var(--st);border-radius:6px}
.life{background:var(--st)}.lg{display:grid;grid-template-columns:1.3fr 1fr 1fr;grid-template-rows:auto auto;gap:18px}
.lg figure{margin:0;position:relative;border-radius:6px;overflow:hidden}.lg img{width:100%;height:100%;object-fit:cover;aspect-ratio:4/3}.lg figure:first-child{grid-row:1/3}.lg figure:first-child img{aspect-ratio:auto;min-height:100%}
.lg figcaption{position:absolute;left:0;right:0;bottom:0;padding:40px 18px 14px;background:linear-gradient(0deg,rgba(15,61,46,.9),transparent);color:#fff;font-size:15px}.lg figcaption b{display:block;font-family:var(--h);font-size:24px;font-weight:500}
.apply .steps{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:24px;list-style:none;padding:0;margin:0;counter-reset:s}
.apply li{counter-increment:s;border-top:3px solid var(--cp);padding-top:16px}.apply li:before{content:"Step " counter(s);font-weight:600;color:var(--cp2);font-size:15px}.apply h3{font-size:26px;margin:4px 0 6px;color:var(--gn)}.apply p{margin:0;color:var(--gr);font-size:16px}
.cta{background:var(--gn);color:#fff}.cta .wrap{display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:20px}.cta h2{font-size:clamp(32px,4vw,48px)}
.btn{display:inline-block;background:var(--cp);color:#fff;text-decoration:none;font:600 17px var(--b);padding:15px 26px;border-radius:4px;border:0;cursor:pointer}.btn.w{background:#fff;color:var(--gn)}
footer{background:#0A2B20;color:#C6D6CD;padding:32px 0;font-size:15px}footer .wrap{display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px}
@media (max-width:980px){.fd{grid-template-columns:1fr}.fl{position:static}.lg{grid-template-columns:1fr 1fr}.lg figure:first-child{grid-column:1/-1;grid-row:auto}.lg figure:first-child img{aspect-ratio:16/9}.apply .steps{grid-template-columns:1fr 1fr}.nums .wrap{grid-template-columns:1fr 1fr}}
@media (max-width:760px){.burger{display:block}.menu{display:none;position:absolute;top:84px;left:0;right:0;background:var(--gn);flex-direction:column;padding:18px 22px;z-index:30}.menu.open{display:flex}.cr{grid-template-columns:1fr}.cr button{grid-row:auto;grid-column:1;justify-self:start;margin-top:8px}.lg,.apply .steps{grid-template-columns:1fr}.hero{min-height:600px}}
@media (prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}

javascript:
(()=>{const $=id=>document.getElementById(id);
const C=[["Accounting and Finance","Undergraduate","Business",["Full time"],"3 years","AAB to ABB","N400"],["Business Management","Undergraduate","Business",["Full time","Part time"],"3 years","ABB to BBB","N100"],["MBA","Postgraduate","Business",["Part time","Online"],"2 years","Degree plus 3 years' work","MBA1"],["Computer Science","Undergraduate","Computing",["Full time"],"3 years","AAA to AAB","G400"],["Data Science","Postgraduate","Computing",["Full time","Online"],"1 year","2:1 degree","DS01"],["Cyber Security","Undergraduate","Computing",["Full time","Part time"],"3 years","ABB","G550"],["Nursing (Adult)","Undergraduate","Health",["Full time"],"3 years","BBB plus interview","B740"],["Physiotherapy","Undergraduate","Health",["Full time"],"3 years","AAB plus interview","B160"],["Public Health","Postgraduate","Health",["Part time","Online"],"2 years","2:2 degree","PH02"],["English Literature","Undergraduate","Arts and humanities",["Full time","Part time"],"3 years","ABB","Q300"],["History","Undergraduate","Arts and humanities",["Full time"],"3 years","ABB to BBB","V100"],["Creative Writing","Postgraduate","Arts and humanities",["Part time","Online"],"2 years","Degree or portfolio","CW01"],["Biology","Undergraduate","Science",["Full time"],"3 years","AAB to ABB","C100"],["Environmental Science","Undergraduate","Science",["Full time"],"3 years","ABB","F750"],["Law (LLB)","Undergraduate","Law",["Full time","Part time"],"3 years","AAA to AAB","M100"],["Law conversion (PGDL)","Postgraduate","Law",["Full time","Online"],"1 year","Any degree","PGDL"]];
const S=new Set();
function draw(){const q=$('q').value.trim().toLowerCase(),lv=$('lv').value,sb=$('sb').value,md=[...document.querySelectorAll('.ck input:checked')].map(i=>i.value);
const r=C.filter(c=>(!q||c[0].toLowerCase().includes(q))&&(!lv||c[1]===lv)&&(!sb||c[2]===sb)&&c[3].some(m=>md.includes(m)));
$('cnt').innerHTML=`<b>${r.length}</b> course${r.length===1?'':'s'} found`;$('sl').textContent='Shortlist: '+S.size;
$('res').innerHTML=r.length?r.map(c=>`<article class="cr"><div><span class="lv">${c[1]}, ${c[2]}</span><h3>${c[0]}</h3><dl><div><dt>Length</dt><dd>${c[4]}</dd></div><div><dt>Entry</dt><dd>${c[5]}</dd></div><div><dt>Mode</dt><dd>${c[3].join(', ')}</dd></div><div><dt>Code</dt><dd>${c[6]}</dd></div></dl></div><button type="button" data-c="${c[6]}" aria-pressed="${S.has(c[6])}">${S.has(c[6])?'On shortlist ✓':'Add to shortlist'}</button></article>`).join(''):'<p class="none">No courses match these filters. Try clearing the keyword or ticking more study modes.</p>'}
$('ff').addEventListener('input',draw);$('ff').onsubmit=e=>e.preventDefault();
$('res').onclick=e=>{const b=e.target.closest('button');if(!b)return;const c=b.dataset.c;S.has(c)?S.delete(c):S.add(c);draw()};
$('rs').onclick=()=>{$('q').value='';$('lv').value='';$('sb').value='';document.querySelectorAll('.ck input').forEach(i=>i.checked=true);draw()};
$('hsf').onsubmit=e=>{e.preventDefault();$('q').value=$('hq').value;draw();$('courses').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})};draw();
})();
(()=>{const b=document.querySelector('.burger'),m=document.getElementById('menu'),y=document.getElementById('yr');
if(b&&m){b.addEventListener('click',()=>{const o=m.classList.toggle('open');b.setAttribute('aria-expanded',o)});
m.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{m.classList.remove('open');b.setAttribute('aria-expanded',false)}))}
if(y)y.textContent=new Date().getFullYear()})();
